// ERRADO: Construir SQL como string (SQL injection!)
const user = await db.query(
  "SELECT * FROM users WHERE email = '" + email + "'"
);

// CERTO: Prisma type-safe
const user = await prisma.user.findUnique({
  where: { email }
}); // Sem SQL injection, type-safe

// RUIM: include traz TODAS lições (50 por user)
const users = await prisma.user.findMany({
  take: 100,
  include: { lessons: true }
}); // 100 users * 50 lessons = 5000 linhas, lento

// BOM: include com where e select
const users = await prisma.user.findMany({
  take: 100,
  include: {
    lessons: {
      where: { status: 'completed' }, // Filtrar
      select: { id: true, status: true } // Só necessário
    }
  }
}); // Apenas lições completadas, apenas IDs + status

