// Agregação complexa em Prisma (verboso)
const result = await prisma.user.groupBy({
  by: ['id'],
  _count: { lessons: true }
});

// Melhor: SQL raw (mais claro)
const result = await prisma.$queryRaw`
  SELECT u.id, COUNT(p.id) as lessons_completed
  FROM users u
  LEFT JOIN lesson_progress p ON u.id = p.user_id AND p.status = 'completed'
  GROUP BY u.id
  HAVING COUNT(p.id) > 5
`;
